create extension if not exists "uuid-ossp";
create table users(id uuid primary key default uuid_generate_v4(),email varchar(255) unique not null,password_hash varchar(255) not null,display_name varchar(120) not null,role varchar(20) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table trips(id uuid primary key default uuid_generate_v4(),user_id uuid not null references users(id),title varchar(255) not null,description text,start_date date,end_date date,cover_image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table destinations(id uuid primary key default uuid_generate_v4(),trip_id uuid not null references trips(id),name varchar(255) not null,city varchar(255),country varchar(255) not null,latitude numeric(9,6),longitude numeric(9,6),description text,cover_image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table memories(id uuid primary key default uuid_generate_v4(),destination_id uuid not null references destinations(id),title varchar(255) not null,subtitle text,story text not null,memory_date date not null,visibility varchar(20) not null,cover_media_id uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table media(id uuid primary key default uuid_generate_v4(),memory_id uuid not null references memories(id) on delete cascade,type varchar(20) not null,storage_key text,url text not null,thumbnail_url text,title varchar(255),caption text,mime_type varchar(100),file_size bigint,sort_order int not null default 0,created_at timestamptz not null default now());alter table memories add constraint fk_cover_media foreign key(cover_media_id) references media(id);
create table locations(id uuid primary key default uuid_generate_v4(),memory_id uuid not null references memories(id) on delete cascade,name varchar(255) not null,description text,latitude numeric(9,6) not null,longitude numeric(9,6) not null,visited_at timestamptz,sort_order int not null default 0);
create table timeline_events(id uuid primary key default uuid_generate_v4(),memory_id uuid not null references memories(id) on delete cascade,title varchar(255) not null,description text,event_time varchar(16) not null,location_id uuid references locations(id),media_id uuid references media(id),sort_order int not null default 0);
create table nfc_tags(id uuid primary key default uuid_generate_v4(),token varchar(80) unique not null,memory_id uuid not null references memories(id) on delete cascade,active boolean not null default true,scan_count bigint not null default 0,last_scanned_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index idx_memories_destination on memories(destination_id);create index idx_memories_visibility on memories(visibility);create index idx_memories_date on memories(memory_date);create index idx_nfc_token on nfc_tags(token);create index idx_nfc_active on nfc_tags(active);create index idx_media_memory on media(memory_id);create index idx_locations_memory on locations(memory_id);
